export const v_driver_state = pgView('v_driver_state', {
  duty_session_id: uuid(),
  user_id: uuid(),
  venue_id: uuid(),
  dispatch_pool_id: uuid(),
  duty_status: text(),
  available_since: timestamp({ withTimezone: true, mode: 'string' }),
  connection_state: text(),
  last_heartbeat_at: timestamp({ withTimezone: true, mode: 'string' }),
  active_task_id: uuid(),
  active_task_type: text(),
  next_task_id: uuid(),
  driver_state: text(),
}).as(
  sql`SELECT ds.id AS duty_session_id, ds.user_id, ds.venue_id, ds.dispatch_pool_id, ds.status AS duty_status, ds.available_since, ds.connection_state, ds.last_heartbeat_at, act.id AS active_task_id, act.type AS active_task_type, nxt.id AS next_task_id, CASE WHEN ds.status = 'on_break'::text THEN 'on_break'::text WHEN act.id IS NOT NULL AND nxt.id IS NOT NULL THEN 'busy_with_next'::text WHEN act.type = ANY (ARRAY['park'::text, 'repark'::text]) THEN 'intake_parking'::text WHEN act.type = 'retrieve'::text THEN 'retrieving'::text ELSE 'available'::text END AS driver_state FROM duty_sessions ds LEFT JOIN tasks act ON act.assignee_id = ds.user_id AND (act.status = ANY (ARRAY['accepted'::text, 'in_progress'::text])) LEFT JOIN tasks nxt ON nxt.assignee_id = ds.user_id AND nxt.status = 'assigned_waiting'::text WHERE ds.status <> 'ended'::text`,
);

export const v_pool_queue = pgView('v_pool_queue', {
  dispatch_pool_id: uuid(),
  task_id: uuid(),
  ticket_id: uuid(),
  cycle_id: uuid(),
  status: text(),
  priority_at: timestamp({ withTimezone: true, mode: 'string' }),
  // You can use { mode: "bigint" } if numbers are exceeding js number limitations
  seq: bigint({ mode: 'number' }),
  active_offer_id: uuid(),
  active_offer_mode: text(),
  offer_expires_at: timestamp({ withTimezone: true, mode: 'string' }),
}).as(
  sql`SELECT t.dispatch_pool_id, t.id AS task_id, t.ticket_id, t.cycle_id, t.status, t.priority_at, t.seq, o.id AS active_offer_id, o.mode AS active_offer_mode, o.expires_at AS offer_expires_at FROM tasks t LEFT JOIN task_offers o ON o.task_id = t.id AND o.status = 'active'::text WHERE t.type = 'retrieve'::text AND (t.status = ANY (ARRAY['queued'::text, 'offered'::text, 'broadcast'::text])) ORDER BY t.dispatch_pool_id, t.priority_at, t.seq`,
);

